        ref?: Ref<FragmentInstance> | undefined;
    }

    interface SubmitEvent<T = Element> extends SyntheticEvent<T, NativeSubmitEvent> {
        /**
         * Only available in react@canary
         */
        submitter: HTMLElement | null;
    }
}

