/**
 * Shared identifiers for the app's view transitions.
 *
 * These are stringly-typed on both ends and fail silently — a name that doesn't
 * match between two pages just degrades to a plain cross-fade rather than
 * erroring — so both sides derive them from here.
 */

/**
 * `view-transition-name` for a product's image. The grid thumbnail and the
 * detail hero share it, which is what lets React pair them and morph one into
 * the other instead of independently fading each out and in.
 */
export function productImageName(slug: string) {
  return `product-image-${slug}`
}

/** Navigating deeper into the catalogue (grid → product detail). */
export const NAV_FORWARD = 'nav-forward'

/** Navigating back out of it (product detail → grid). */
export const NAV_BACK = 'nav-back'

/**
 * `view-transition-class` for the page wrapper, keyed by the transition type
 * that `<Link transitionTypes>` fed to `React.addTransitionType`. `default`
 * covers navigations we can't tag — browser back/forward buttons, which the
 * router drives itself — with a non-directional cross-fade.
 */
export const pageTransitionClass = {
  [NAV_FORWARD]: 'vt-page-forward',
  [NAV_BACK]: 'vt-page-back',
  default: 'vt-page-fade',
}

/** `view-transition-class` for a Suspense fallback → content reveal. */
export const REVEAL_CLASS = 'vt-reveal'

/** `view-transition-class` for the thumbnail ↔ hero morph. */
export const PRODUCT_IMAGE_CLASS = 'vt-product-image'

