import type { Metadata } from 'next'
import { ViewTransition } from 'react'
import { pageTransitionClass } from '@/lib/transitions'
import './globals.css'

export const metadata: Metadata = {
  title: 'Product Gallery',
  description: 'A simple product gallery',
}

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode
}>) {
  return (
    <html lang="en">
      <body>
        {/*
          The root layout never unmounts, so a navigation reaches this
          `<ViewTransition>` as an update to its children — that's the hook the
          directional slide hangs off. The `.page` wrapper is here so the
          animated box has the same geometry on every route; otherwise the group
          would morph its width/height at the same time and fight the slide.
        */}
        <ViewTransition default={pageTransitionClass}>
          <div className="page">{children}</div>
        </ViewTransition>
      </body>
    </html>
  )
}

