import Link from 'next/link'
import { ViewTransition } from 'react'
import { products } from '@/lib/products'
import {
  NAV_FORWARD,
  PRODUCT_IMAGE_CLASS,
  productImageName,
} from '@/lib/transitions'

export function ProductGrid() {
  return (
    <div className="product-grid">
      {products.map((product) => (
        <Link
          key={product.slug}
          href={`/product/${product.slug}`}
          className="product-card"
          transitionTypes={[NAV_FORWARD]}
        >
          {/*
            Same `name` as the hero on the detail page. React sees one instance
            unmounting and another with that name mounting in the same
            navigation, treats it as a shared element, and morphs between the
            two boxes instead of fading them independently.
          */}
          <ViewTransition
            name={productImageName(product.slug)}
            share={PRODUCT_IMAGE_CLASS}
          >
            <div
              className="product-image"
              style={{ backgroundColor: product.color }}
            />
          </ViewTransition>
          <h2>{product.name}</h2>
          <p>${product.price}</p>
        </Link>
      ))}
    </div>
  )
}

