/* ==========================================================================
   View transitions

   The `.vt-*` selectors are `view-transition-class` values set from JSX via the
   `default` / `share` props on `<ViewTransition>`; see lib/transitions.ts.
   ========================================================================== */

:root {
  --vt-duration: 320ms;
  --vt-reveal-duration: 240ms;
  --vt-ease: cubic-bezier(0.4, 0, 0.2, 1);
}

@keyframes vt-slide-out-to-left {
  to {
    opacity: 0;
    transform: translateX(-48px);
  }
}

@keyframes vt-slide-in-from-right {
  from {
    opacity: 0;
    transform: translateX(48px);
  }
}

@keyframes vt-slide-out-to-right {
  to {
    opacity: 0;
    transform: translateX(48px);
  }
}

@keyframes vt-slide-in-from-left {
  from {
    opacity: 0;
    transform: translateX(-48px);
  }
}

@keyframes vt-fade-out {
  to {
    opacity: 0;
  }
}

@keyframes vt-fade-in {
  from {
    opacity: 0;
  }
}

/* Page navigation: the outgoing page leaves in the direction of travel and the
   incoming one follows it in. */
::view-transition-old(.vt-page-forward) {
  animation: vt-slide-out-to-left var(--vt-duration) var(--vt-ease) both;
}

::view-transition-new(.vt-page-forward) {
  animation: vt-slide-in-from-right var(--vt-duration) var(--vt-ease) both;
}

::view-transition-old(.vt-page-back) {
  animation: vt-slide-out-to-right var(--vt-duration) var(--vt-ease) both;
}

::view-transition-new(.vt-page-back) {
  animation: vt-slide-in-from-left var(--vt-duration) var(--vt-ease) both;
}

/* Untagged navigations (browser back/forward) have no direction to honour. */
::view-transition-old(.vt-page-fade) {
  animation: vt-fade-out var(--vt-duration) var(--vt-ease) both;
}

::view-transition-new(.vt-page-fade) {
  animation: vt-fade-in var(--vt-duration) var(--vt-ease) both;
}

/* Shared element: the product image morphs between thumbnail and hero. */
::view-transition-group(.vt-product-image) {
  animation-duration: var(--vt-duration);
  animation-timing-function: var(--vt-ease);
  /* Fly above the page underneath it, which is sliding at the same time. */
  z-index: 1;
}

::view-transition-old(.vt-product-image),
::view-transition-new(.vt-product-image) {
  animation-duration: var(--vt-duration);
  animation-timing-function: var(--vt-ease);
  /*
   * The thumbnail is 4:3 and the hero is 1:1. By default a snapshot keeps its
   * natural height while the group's width animates, which shears the image as
   * the aspect ratio changes; pinning both snapshots to the group box and
   * cropping instead keeps the morph clean.
   */
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/*
 * Suspense reveal: skeleton cross-fades into content while the box animates to
 * its new height. Deliberately no width/height override here — letting the
 * snapshots keep their natural height is what makes the height change read as a
